create view public.phase1_forebet_identity_actionability_v2 as select hkjc_event_id, canonical_tournament, source_competition, source_home_team, source_away_team, forebet_state, identity_status, competition_master_hit, home_context_master_hit, away_context_master_hit, case when identity_status = 'CONTEXT_VERIFIED' and home_context_master_hit is true and away_context_master_hit is true then 'RESOLVED_STATIC_MASTER' when forebet_state = 'UNRESOLVED' and source_home_team is null and source_away_team is null then 'PROVIDER_SURFACE_ABSENCE' when source_home_team is not null and (home_context_master_hit is not true or away_context_master_hit is not true) then 'ACTIONABLE_IDENTITY_GAP' when source_competition is not null and competition_master_hit is not true then 'ACTIONABLE_LEAGUE_GAP' else 'REVIEW_NON_IDENTITY' end as action_class from public.forebet_identity_candidate_queue_v;
